---@class HomeCardWord
local HomeCardWord = Class('HomeCardWord')

function HomeCardWord:__init()
    self.isEnterRoleSwitch = false
    self.behaviourAction = nil
    self.startTime = time()
end

function HomeCardWord:__delete()
    self.behaviourAction = nil
    self.startTime = nil
end

function HomeCardWord:Start()
    if not EasyTouch.instance.enable then
        EasyTouch.instance.enable = true ---启动easytouch实例，因战斗出来会被禁用掉
    end
    ---@type HedgehogTeam.EasyTouch.QuickTap
    local quickTap = KTool.GetOrAddComponent(self.controller.gameObject, typeof(CS.HedgehogTeam.EasyTouch.QuickTap))
    if not isNull(quickTap) then
        quickTap.onTap:AddListener(Bind(self, self.OnQuickTapAction))
    end

    ---@type HedgehogTeam.EasyTouch.QuickSwipe
    local quickSwipe = KTool.GetOrAddComponent(self.controller.gameObject, typeof(QuickSwipe))
    quickSwipe.quickActionName = "HSwipe"
    quickSwipe.actionTriggering = 0 --in progress
    quickSwipe.swipeDirection = 1 -- 水平方向的swipe
    quickSwipe.enableSimpleAction = true
    quickSwipe.enablePickOverUI = true
    quickSwipe.directAction = 2 ---rotate Local
    quickSwipe.axesAction = 1 ---Y轴
    quickSwipe.sensibility = 0.32 ---Y轴
    quickSwipe.enabled = false

    self.__UpdateQuickSwipeEnabledState = Events.AddListener(Constants.EventNames.UIEventHomeShowOrHideCharacterSwipe, Bind(self, self.UpdateQuickSwipeEnabledState))
    --local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    --behaviourAction.UpdateAction = Bind(self, self.OnUpdate)
    --self.behaviourAction = behaviourAction
end

---OnCoroutine
---协程事件
function HomeCardWord:OnUpdate()
    if time() - self.startTime >= TIME_SPAN then
        self.startTime = time()
        if KTool.IsActive(self.controller.gameObject) then
            ---处理静态情况下的台词的逻辑
            print('-----处理台词---->>')
        end
    end
end

---OnQuickTapAction
---@param gesture HedgehogTeam.EasyTouch.Gesture
function HomeCardWord:OnQuickTapAction(gesture)
    ----发送点击的角色id
    Events.Broadcast(Constants.EventNames.UIEventHomeRoleQuickTapAction)
    --if self.isEnterRoleSwitch then return end
    --self:OnEventHomeShowOrHideChangeCharacter(false)
end

function HomeCardWord:UpdateQuickSwipeEnabledState(enabled)
    if not isNull(self.controller.gameObject) then
        ---@type HedgehogTeam.EasyTouch.QuickSwipe
        local quickSwipe = KTool.GetComponent(self.controller.gameObject, typeof(QuickSwipe))
        if quickSwipe then
            quickSwipe.enabled = enabled
        end
    end
end

function HomeCardWord:OnDestroy()
    if self.__UpdateQuickSwipeEnabledState then
        Events.RemoveListener(Constants.EventNames.UIEventHomeShowOrHideCharacterSwipe, self.__UpdateQuickSwipeEnabledState)
        self.__UpdateQuickSwipeEnabledState = nil
    end

    if self.behaviourAction then
        self.behaviourAction.UpdateAction = nil
    end
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return HomeCardWord